/**
 * GENERATED by scripts/watercolours.mjs; do not edit by hand.
 *
 * Add paintings by dropping files into Watercolours/<Category>/<Series>/ and
 * running `node scripts/watercolours.mjs`. Series order and the nicer titles
 * live in that script.
 *
 * Not a case study but a gallery. Painting is on the CV under Outside work, and
 * it belongs on the site for the same reason: it says something true that the
 * product work cannot.
 */
export type Painting = {
  /** 2000px long edge, what the gallery shows. */
  src: string;
  /** 700px, what the grid and the filmstrip show. */
  thumb?: string;
  title?: string;
  note?: string;
};

export type Series = {
  id: string;
  name: string;
  blurb?: string;
  paintings: Painting[];
};

export type Category = {
  id: string;
  name: string;
  blurb?: string;
  paintings?: Painting[];
  series?: Series[];
};

